// App themes: the backdrop behind every screen, and for some themes the
// glass tint, text colour and accent too. The look itself lives in
// app/themes.css (generated by scripts/generate-theme-css.mjs), keyed by a
// `theme-<id>` class on <html>; this file holds the list, the choice, and
// how it is applied.
//
// The choice is per device (localStorage), like the Liquid Glass switch.
// Premium themes can be previewed by anyone, but only kept with Premium.

export type ThemeId = 'original' | 'mono' | 'plum-duotone' | 'paper' | 'rose-glass'

export interface AppTheme {
  id: ThemeId
  premium: boolean
  /** The swatch in the picker: a small version of the backdrop. */
  swatch: string
  /** Dark text on a light backdrop. */
  light?: boolean
}

export const THEMES: AppTheme[] = [
  { id: 'original', premium: false, swatch: "url('/bg.jpeg') 62% 50% / cover" },
  { id: 'mono', premium: false, swatch: "url('/themes/mono.jpg') 62% 50% / cover" },
  { id: 'plum-duotone', premium: false, swatch: "url('/themes/plum-duotone.jpg') 62% 50% / cover" },
  {
    id: 'paper',
    premium: true,
    light: true,
    swatch: 'radial-gradient(70% 40% at 85% 10%, #fde1c4 0%, transparent 70%), radial-gradient(80% 45% at 10% 90%, #f5c4a1 0%, transparent 70%), linear-gradient(180deg, #fbf1e4 0%, #f1d9c0 100%)',
  },
  {
    id: 'rose-glass',
    premium: true,
    swatch: 'linear-gradient(165deg, #9f1239 0%, #f43f5e 45%, #fdba74 100%)',
  },
]

export const DEFAULT_THEME: ThemeId = 'original'
export const THEME_STORAGE_KEY = 'sprind:theme'
const THEME_EVENT = 'sprind:theme-change'

export const themeById = (id: string | null | undefined): AppTheme =>
  THEMES.find((t) => t.id === id) ?? THEMES[0]

// Runs inline in <head>, before first paint, so the page never flashes the
// default theme. Plain ES5: it is not compiled.
export const themeBootScript = `(function () {
  try {
    var id = localStorage.getItem(${JSON.stringify(THEME_STORAGE_KEY)});
    var known = ${JSON.stringify(THEMES.map((t) => t.id))};
    if (id && id !== ${JSON.stringify(DEFAULT_THEME)} && known.indexOf(id) > -1) {
      document.documentElement.classList.add('theme-' + id);
    }
  } catch (e) {}
})();`

/** The theme on screen now (a preview counts). */
export function currentTheme(): ThemeId {
  if (typeof document === 'undefined') return DEFAULT_THEME
  const cls = Array.from(document.documentElement.classList).find((c) => c.startsWith('theme-'))
  return themeById(cls?.slice(6)).id
}

/** The theme the user chose and kept. */
export function savedTheme(): ThemeId {
  try {
    return themeById(localStorage.getItem(THEME_STORAGE_KEY)).id
  } catch {
    return DEFAULT_THEME
  }
}

/** Puts a theme on screen, cross-fading the backdrop. Does not save it. */
function show(id: ThemeId) {
  const root = document.documentElement
  const from = getComputedStyle(root).getPropertyValue('--app-backdrop').trim()
  for (const t of THEMES) root.classList.remove(`theme-${t.id}`)
  if (id !== DEFAULT_THEME) root.classList.add(`theme-${id}`)
  window.dispatchEvent(new CustomEvent(THEME_EVENT, { detail: { id, from } }))
}

// A premium theme being tried on, and what to go back to.
let preview: { id: ThemeId; previous: ThemeId } | null = null

/** Chooses a theme and keeps it. */
export function setTheme(id: ThemeId) {
  preview = null
  try {
    if (id === DEFAULT_THEME) localStorage.removeItem(THEME_STORAGE_KEY)
    else localStorage.setItem(THEME_STORAGE_KEY, id)
  } catch {}
  show(id)
}

/** Shows a theme without keeping it, until it is kept or reverted. */
export function previewTheme(id: ThemeId) {
  const previous = preview?.previous ?? savedTheme()
  preview = { id, previous }
  show(id)
}

export const isPreviewing = () => preview !== null

/** Keeps the theme being previewed (after a purchase). */
export function keepPreview() {
  if (preview) setTheme(preview.id)
}

/** Goes back to the kept theme, if a preview is showing. */
export function revertPreview() {
  if (!preview) return
  const { previous } = preview
  preview = null
  show(previous)
}

/** Subscribes to theme changes: the new id, and the backdrop it replaced. */
export function onThemeChange(fn: (id: ThemeId, fromBackdrop: string) => void) {
  const handler = (e: Event) => {
    const { id, from } = (e as CustomEvent<{ id: ThemeId; from: string }>).detail
    fn(id, from)
  }
  window.addEventListener(THEME_EVENT, handler)
  return () => window.removeEventListener(THEME_EVENT, handler)
}
